"""
Данные 40 новых категорий × 10 Q&A для расширения до 60 категорий.
Формат: slug, name, intro, articles (список dict: slug, question, meta, body).
"""


def _qa(slug: str, question: str, meta: str, *paragraphs: str) -> dict:
    body = "\n".join(f"<p>{p}</p>" for p in paragraphs)
    return {"slug": slug, "question": question, "meta": meta, "body": body}


def _meta(day: str, num: int, city: str) -> str:
    return f"{day}, вопрос №{num}, г. {city}"


